const staticData = $getWorkflowStaticData('global');

const TELEGRAM_BOT_TOKEN = '8556679902:AAGFg5yBUkF_6EtWHgf3TwTlxva0vbhQvVE';
const TELEGRAM_CHAT_ID = '5084875115';

const inputItems = $input.all();
let issues = [];
if (inputItems.length === 1 && Array.isArray(inputItems[0].json)) {
  issues = inputItems[0].json;
} else {
  issues = inputItems.map(i => i.json);
}

const todayStr = new Date().toLocaleDateString('en-CA', {timeZone: 'America/New_York'});
if (staticData.last_check_date !== todayStr) {
  staticData.notified_today_done = false;
  staticData.last_check_date = todayStr;
}

function parseDt(s) {
  return new Date(s.replace(/(\.[0-9]{1,3})[0-9]*/g, '$1'));
}

const todayStart = new Date('2026-03-30T00:00:00-04:00');

const todayNotDone = issues.filter(i => {
  if (!i.created_at) return false;
  const d = parseDt(i.created_at);
  return d >= todayStart && !['closed', 'released', 'cancelled'].includes(i.status);
});

const openNotMichael = issues.filter(i =>
  i.status === 'open' && i.assignee && i.assignee !== 'michael'
);

const results = [];

if (todayNotDone.length === 0 && !staticData.notified_today_done) {
  const resp = await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      chat_id: TELEGRAM_CHAT_ID,
      text: '\u2705 All issues created today are now closed/released.'
    })
  });
  const body = await resp.json();
  staticData.notified_today_done = true;
  results.push({condition: 'today_done', sent: true, telegram_ok: resp.ok});
} else {
  results.push({condition: 'today_done', sent: false, remaining: todayNotDone.length, already_notified: !!staticData.notified_today_done});
}

if (openNotMichael.length === 0 && !staticData.notified_queue_clear) {
  const resp = await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      chat_id: TELEGRAM_CHAT_ID,
      text: '\u2705 All open issues (not assigned to you) have been worked through.'
    })
  });
  const body = await resp.json();
  staticData.notified_queue_clear = true;
  results.push({condition: 'queue_clear', sent: true, telegram_ok: resp.ok});
} else {
  results.push({condition: 'queue_clear', sent: false, remaining: openNotMichael.length, already_notified: !!staticData.notified_queue_clear});
}

return results.map(r => ({json: r}));
